import {draftOrder,recordInvoice,transition} from './orders.mjs';
const supplier={name:'',handle:''},orders=[];
let loading=null,loadError='',loaded=false,serverMode=false,connected=false,orderFilter='active',orderQuery='';
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Almaty',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const overdue=o=>o.status==='awaiting_payment'&&o.invoice?.due<today();
async function request(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(20000)});const data=await r.json();if(!r.ok)throw Error(data.error||'Сервер недоступен.');return data;}
async function load(){const data=await request('./api/orders');orders.splice(0,orders.length,...data.orders);serverMode=true;connected=data.connected;loaded=true;}

const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(v)+' ₸';
const statuses={draft:'Черновик · не отправлен',awaiting_payment:'Ожидает оплаты',paid:'Оплачен · отмечено вами',received:'Получен · отмечено вами',cancelled:'Отменён',sent:'Отправлен в Telegram',sending:'Отправка · не повторяйте',delivery_unknown:'Доставка не подтверждена · проверьте чат'};
export function supplierPanel(app,result,notify,source,budget=null){
  const panel=document.createElement('section');panel.className='panel supplier-panel';
  const pending=orders.filter(o=>o.status==='awaiting_payment');
  const stats=app.querySelector('#supplier-stats');
  if(stats)stats.innerHTML=[[orders.filter(o=>!['received','cancelled'].includes(o.status)).length,'Активных заказов'],[money(pending.reduce((s,o)=>s+o.invoice.amount,0)),'К оплате'],[pending.filter(overdue).length,'Просроченных счетов']].map(([value,label])=>`<div class="stat"><div class="stat-label">${label}</div><div class="stat-value">${value}</div></div>`).join('');
  panel.innerHTML=`${loadError?`<div class="error-box" role="alert">${esc(loadError)} <button class="button" id="retry-orders">Повторить</button></div>`:''}<div class="panel-head"><h2>Закупки через Telegram</h2><span class="badge neutral">${connected?'Telegram подключён':'Telegram не подключён здесь'}</span></div><p class="note">Подготовьте заказ и проверьте его перед отправкой. Получатель должен открыть <a href="https://t.me/qadam_ai_supply_bot" target="_blank" rel="noopener noreferrer">@qadam_ai_supply_bot</a> и нажать «Старт». ${serverMode?'<button class="button" id="sync-telegram">Обновить Telegram</button>':''}</p>${pending.length?`<div class="callout"><strong>Ожидают оплаты: ${pending.length}</strong> · ${money(pending.reduce((s,o)=>s+o.invoice.amount,0))}<br>Проверьте счёт и оплатите напрямую поставщику.</div>`:''}<details class="new-order" ${budget?'open':''}><summary>＋ Новый заказ</summary>${budget?'<p class="callout">Количество заполнено из бюджетного сценария. Проверьте позиции поставщика перед подтверждением.</p>':''}<form id="supplier-form"><div class="supplier-fields"><label>Поставщик<input id="supplier-name" maxlength="120" required value="${esc(supplier.name)}" placeholder="Название компании"></label><label>Telegram поставщика<input id="supplier-handle" maxlength="33" required value="${esc(supplier.handle)}" placeholder="@username"></label></div><p class="meta">Один заказ — один поставщик. Оставьте только его товары, для остальных укажите 0.</p><div class="table-wrap"><table><thead><tr><th>Товар</th><th>Количество, шт.</th></tr></thead><tbody>${result.products.map(p=>`<tr><td>${esc(p.name)}<small class="meta"> · ${esc(p.sku)}</small></td><td><input class="order-quantity" data-sku="${esc(p.sku)}" aria-label="Количество: ${esc(p.name)}" type="number" min="0" max="1000000" step="1" value="${budget?(budget.lines.find(x=>x.sku===p.sku)?.quantity??0):(p.suggested??0)}"></td></tr>`).join('')}</tbody></table></div><button class="button primary" type="submit">Подготовить текст заказа</button></form></details><details class="supplier-help"><summary>Как поставщику выставить счёт</summary><p class="note">Поставщик нажимает «Старт» у бота. После получения заказа он отвечает именно на сообщение заказа: <code>/invoice 15000 2026-10-30 Доставка включена</code>. Это пример суммы и даты. Проверка новых счетов — раз в час или по кнопке «Обновить Telegram».</p></details><div class="order-tools"><label>Найти заказ<input id="order-search" type="search" placeholder="Поставщик, товар или номер" value="${esc(orderQuery)}"></label><label>Показать<select id="order-filter">${[['active','Активные'],['all','Все заказы'],['draft','Черновики'],['awaiting_payment','К оплате'],['overdue','Просроченные'],['sent','Отправленные'],['paid','Оплаченные'],['received','Полученные'],['cancelled','Отменённые']].map(([v,t])=>`<option value="${v}" ${orderFilter===v?'selected':''}>${t}</option>`).join('')}</select></label></div><div id="order-count" class="meta" role="status"></div><div id="orders-list"></div><p class="meta">${serverMode?'Заказы сохранены на сервере.':'Создание заказов доступно после подключения к хранилищу.'} Оплачиваете вы; бот не списывает деньги. Заказы не меняют складские остатки.</p>`;
  app.querySelector('.stats').after(panel);
  if(!serverMode){panel.querySelectorAll('#supplier-form input,#supplier-form button').forEach(el=>el.disabled=true);panel.querySelector('#supplier-form').insertAdjacentHTML('afterbegin','<p class="note" role="status">'+(loadError?'Восстановите связь с хранилищем, чтобы создать заказ.':'Загружаем сохранённые заказы…')+'</p>');}
  const draw=()=>{
    const shown=orders.filter(o=>(orderFilter==='all'||(orderFilter==='active'?!['received','cancelled'].includes(o.status):orderFilter==='overdue'?overdue(o):o.status===orderFilter))&&[o.id,o.supplier.name,o.supplier.handle,o.message].join(' ').toLocaleLowerCase().includes(orderQuery.toLocaleLowerCase()));
    panel.querySelector('#order-count').textContent=`Найдено: ${shown.length}`;
    panel.querySelector('#orders-list').innerHTML=shown.map(o=>`<article class="order-item"><div class="panel-head"><strong>${esc(o.supplier.name)}</strong><span class="badge ${o.status==='awaiting_payment'?'warn':'neutral'}">${overdue(o)?'Просрочен счёт · ':''}${statuses[o.status]}</span></div><div class="meta">№ ${o.id.slice(0,8)} · ${new Date(o.createdAt).toLocaleDateString('ru-RU')} · ${o.source==='demo'?'Учебный заказ · ':''}@${esc(o.supplier.handle)} · оценка ${money(o.estimate)}, цена не подтверждена</div><details><summary>Текст заказа</summary><textarea readonly aria-label="Текст заказа ${esc(o.supplier.name)}">${esc(o.message)}</textarea><button class="button" data-copy="${o.id}">Скопировать текст</button><a class="button" href="https://t.me/${encodeURIComponent(o.supplier.handle)}" target="_blank" rel="noopener noreferrer">Открыть чат</a><p class="meta">Открытие чата не отправляет сообщение. Можно отправить текст вручную со своего аккаунта.</p>${o.status==='draft'?`<label class="form-control"><input type="checkbox" id="approve-${o.id}" ${!connected||o.source==='demo'?'disabled':''}> Подтверждаю состав и отправку @${esc(o.supplier.handle)}</label><button class="button primary" data-send="${o.id}" ${!connected||o.source==='demo'?'disabled':''}>Подтвердить и отправить ботом</button><p class="meta">${o.source==='demo'?'Учебный заказ: отправка запрещена.':!connected?'Отправка будет доступна после подключения сервера к Telegram.':'Цена уточняется поставщиком; это запрос на согласование.'}</p>`:''}</details>${['draft','sent','awaiting_payment'].includes(o.status)?`<details><summary>Поставщик прислал счёт</summary><p class="note">Внесите подтверждённые сумму и срок. Это ручная запись, не ответ Telegram-бота.</p><form data-invoice="${o.id}" class="invoice-form"><label>К оплате, ₸<input name="amount" type="number" min="0.01" step="0.01" required value="${o.invoice?.amount??''}"></label><label>Оплатить до<input name="due" type="date" required value="${o.invoice?.due??''}"></label><label>Комментарий к счёту<textarea name="note" maxlength="1000">${esc(o.invoice?.note??'')}</textarea></label><button class="button" type="submit">Сохранить напоминание</button></form></details>`:''}${o.invoice?`<div class="callout">${money(o.invoice.amount)} · срок ${o.invoice.due} · ${o.invoice.source==='telegram'?'Счёт из Telegram':'Внесено вручную'}${o.invoice.note?`<br>${esc(o.invoice.note)}`:''}</div>`:''}<div class="toolbar">${o.status==='awaiting_payment'?`<button class="button primary" data-order="${o.id}" data-status="paid">Я оплатил(а)</button>`:''}${o.status==='paid'?`<button class="button" data-order="${o.id}" data-status="received">Товар получен</button>`:''}${['draft','sent','awaiting_payment'].includes(o.status)?`<button class="button" data-order="${o.id}" data-status="cancelled">Отменить в плане</button>`:''}</div></article>`).join('')||'<div class="empty">Здесь пока нет заказов. Создайте новый или измените фильтр.</div>';
    panel.querySelectorAll('[data-send]').forEach(b=>b.onclick=async()=>{
      const i=orders.findIndex(o=>o.id===b.dataset.send);if(!panel.querySelector('#approve-'+b.dataset.send).checked){notify('Сначала подтвердите состав и получателя.');return;}
      b.disabled=true;try{orders[i]=await request('./api/orders/'+orders[i].id,{action:'send',confirm:true,version:orders[i].version});refresh();notify('Заказ отправлен в Telegram.');}catch(e){await load().catch(()=>{});refresh();notify(e.message);}
    });
    panel.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(orders.find(o=>o.id===b.dataset.copy).message);notify('Текст скопирован. Сообщение не отправлено.');}catch{notify('Выделите текст заказа и скопируйте его вручную.');}});
    panel.querySelectorAll('[data-invoice]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{const i=orders.findIndex(o=>o.id===f.dataset.invoice);const invoice=Object.fromEntries(new FormData(f));orders[i]=serverMode?await request('./api/orders/'+orders[i].id,{action:'invoice',invoice,version:orders[i].version}):recordInvoice(orders[i],invoice);refresh();notify('Напоминание об оплате добавлено в план.');}catch(error){notify(error.message);}});
    panel.querySelectorAll('[data-order]').forEach(b=>b.onclick=async()=>{try{const i=orders.findIndex(o=>o.id===b.dataset.order);orders[i]=serverMode?await request('./api/orders/'+orders[i].id,{action:b.dataset.status,version:orders[i].version}):transition(orders[i],b.dataset.status);refresh();notify('Статус изменён вами. Остатки не изменены.');}catch(error){notify(error.message);}});
  };
  const refresh=()=>{if(!panel.isConnected)return;panel.remove();supplierPanel(app,result,notify,source,budget);};
  panel.querySelector('#supplier-form').onsubmit=async e=>{e.preventDefault();const submit=e.currentTarget.querySelector('[type=submit]');if(submit.disabled)return;submit.disabled=true;try{if(!serverMode)throw Error('Хранилище заказов недоступно. Нажмите «Повторить» перед созданием заказа.');const quantities=Object.fromEntries([...panel.querySelectorAll('.order-quantity')].map(el=>[el.dataset.sku,el.value]));const draft=draftOrder({name:panel.querySelector('#supplier-name').value,handle:panel.querySelector('#supplier-handle').value},result.products,quantities);draft.source=source;Object.assign(supplier,draft.supplier);if(orders.some(o=>o.status==='draft'&&o.message===draft.message))throw Error('Такой черновик уже есть ниже.');const saved=await request('./api/orders',{supplier:draft.supplier,lines:draft.lines,source});orders.unshift(saved);orderFilter='draft';orderQuery='';refresh();notify('Черновик готов. Проверьте текст заказа.');}catch(error){notify(error.message);}finally{submit.disabled=false;}};
  panel.querySelector('#sync-telegram')?.addEventListener('click',async()=>{try{await request('./api/telegram/sync',{});await load();refresh();notify('Telegram обновлён.');}catch(e){notify(e.message);}});
  panel.querySelector('#order-search').oninput=e=>{orderQuery=e.target.value;draw();};
  panel.querySelector('#order-filter').onchange=e=>{orderFilter=e.target.value;draw();};
  draw();
  const retry=()=>{if(loading)return;loadError='';loading=load().then(()=>{loadError='';}).catch(()=>{serverMode=false;loadError='Не удалось загрузить заказы. Создание временных заказов отключено, чтобы не потерять их.';}).finally(()=>{loading=null;if(panel.isConnected)refresh();});};
  panel.querySelector('#retry-orders')?.addEventListener('click',retry);
  if(!loaded&&!loading&&!loadError)retry();
}

